from ta_pdml_parser.pdml_rrc_parser import PdmlRrcParser
from ta_pdml_parser import parser_factory


__author__ = 'Marcin Siedlarz'


def get_msgs_from_pdml_file(filepath):
    '''
    '''
    pdml_parser = parser_factory.get_pdml_parser()
    with open(filepath, 'r') as pdml_file:
        msg_list = [msg for msg in pdml_parser.iter_msg(pdml_file)]
    return msg_list


def get_msgs_from_pdml_string(pdml_string):
    '''
    '''
    pdml_parser = parser_factory.get_pdml_parser()
    return [msg for msg in pdml_parser.iter_msg(pdml_string)]


def parse_rrc_container(information_element, hex_to_be_parsed):
    '''
    Method for parsing rrc information elements stored inside messages containers
    :param information_element: information_element expected to be stored inside container
    :param hex_to_be_parsed: hex to be parsed
    :return: MessageField encapsulating parsed rrc container
    '''
    pdml_parser = parser_factory.get_pdml_parser()
    return pdml_parser.parse_container('rrc', information_element, hex_to_be_parsed)


